-- Pavucontrol floating
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    match = {
        class = "(.*org.pulseaudio.pavucontrol.*)",
    },
    float = true,
    size = "700 600",
    center = true,
    pin = true,
})

-- ML4W Welcome App floating
hl.window_rule({
    match = {
        class = "(.*waypaper.*)",
    },
    float = true,
    size = "900 700",
    center = true,
    pin = true,
})

